class AdminConfigurations(ValidateBaseModel):
    """
    These configurations show account properties that are overridden either by Alpaca Broker Operations or an automated process.

    These values cannot be modified by the Broker Partners.

    This schema represents the current, effective value of each configuration (e.g. as returned by the get trading account endpoint). For the shape of the payloads broadcast by the **events** streaming API when these values change, see [AdminConfigurationsEvent](#/components/schemas/AdminConfigurationsEvent).
    """

    acct_daily_transfer_limit: Optional[StrictStr] = Field(
        default=None,
        description="Override the correspondent level daily transfer limits",
    )
    allow_instant_ach: Optional[StrictBool] = Field(
        default=None,
        description="If true, the account is allowed to perform instant ACH",
    )
    disable_algodash_access: Optional[StrictBool] = Field(
        default=None, description="If true, the account is allowed to access algo dash"
    )
    disable_api_key: Optional[StrictBool] = Field(
        default=None, description="If true, the account's API key will be disabled"
    )
    disable_crypto: Optional[StrictBool] = Field(
        default=None, description="If true, the account is not allowed to trade cryptos"
    )
    disable_day_trading: Optional[StrictBool] = Field(
        default=None,
        description="If true, the account is not allowed to day trade (e.g. buy and sell the same security on the same day)",
    )
    disable_fractional: Optional[StrictBool] = Field(
        default=None,
        description="If true, the account cannot create orders for fractional share positions",
    )
    disable_shorting: Optional[StrictBool] = Field(
        default=None,
        description="If true the account is not allowed to create short position orders",
    )
    incoming_transfers_blocked: Optional[StrictBool] = Field(
        default=None,
        description="If true, incoming transfers to this account are rejected",
    )
    max_margin_multiplier: Optional[StrictStr] = Field(
        default=None,
        description='The max margin multiplier set by admin for this account. Can be "1", "2", or "4".',
    )
    max_options_trading_level: Optional[AdminConfigurationsMaxOptionsTradingLevel] = (
        None
    )
    outgoing_transfers_blocked: Optional[StrictBool] = Field(
        default=None,
        description="If true, outgoing transfers from this account are rejected",
    )
    restrict_to_liquidation_reasons: Optional[RestrictToLiquidationReasons] = None


class AdminConfigurationsEvent(ValidateBaseModel):
    """
    Represents a change to admin configurations, as broadcast over the **events** streaming API. Only fields whose value changed are included; unrelated update events will not include a flag that did not change.

    Depending on the type of the Admin Configuration, the sent event will behave differently. For bool flags we are only sending the new value.

    For example, the following payload means that the disable_shorting flag was set to true:

    ```
    {
      "disable_shorting": true
    }
    ```

    For other data types, we are embedding the old and new values into the payload. For example changing the max_margin_multiplier from 4 to 1 will yield this payload:

    ```
    {
      "max_margin_multiplier": {
        "from": 4,
        "to": 1
      }
    }
    ```

    Introducing an override value from the default will yield a null value as `from`. For example restricting the max_margin_multiplier to 1 from default will yield the following payload:

    ```
    {
      "max_margin_multiplier": {
        "from": null,
        "to": 1
      }
    }
    ```
    """

    acct_daily_transfer_limit: Optional[
        AdminConfigurationsEventAcctDailyTransferLimit
    ] = None
    allow_instant_ach: Optional[StrictBool] = Field(
        default=None,
        description="If true, the account is allowed to perform instant ACH",
    )
    disable_algodash_access: Optional[StrictBool] = Field(
        default=None, description="If true, the account is allowed to access algo dash"
    )
    disable_api_key: Optional[StrictBool] = Field(
        default=None, description="If true, the account's API key will be disabled"
    )
    disable_crypto: Optional[StrictBool] = Field(
        default=None, description="If true, the account is not allowed to trade cryptos"
    )
    disable_day_trading: Optional[StrictBool] = Field(
        default=None,
        description="If true, the account is not allowed to day trade (e.g. buy and sell the same security on the same day)",
    )
    disable_fractional: Optional[StrictBool] = Field(
        default=None,
        description="If true, the account cannot create orders for fractional share positions",
    )
    disable_shorting: Optional[StrictBool] = Field(
        default=None,
        description="If true the account is not allowed to create short position orders",
    )
    incoming_transfers_blocked: Optional[StrictBool] = Field(
        default=None,
        description="If true, incoming transfers to this account are rejected",
    )
    max_margin_multiplier: Optional[AdminConfigurationsEventMaxMarginMultiplier] = None
    max_options_trading_level: Optional[
        AdminConfigurationsEventMaxOptionsTradingLevel
    ] = None
    outgoing_transfers_blocked: Optional[StrictBool] = Field(
        default=None,
        description="If true, outgoing transfers from this account are rejected",
    )
    restrict_to_liquidation_reasons: Optional[RestrictToLiquidationReasons] = None


